  public async host(
    options: { auto?: boolean; onCode?: (code: string) => void } = {}
  ): Promise<void> {
    const rooms = this.cloud.rooms();
    if (rooms === null) {
      return;
    }
    const attempt = this.restart({
      phase: 'opening',
      role: 'host',
      auto: options.auto ?? false,
    });
    try {
      const { link, offer } = await this.wire.offer();
      if (!this.adopt(link, attempt)) {
        return;
      }
      const room = await rooms.open(offer);
      if (attempt !== this.attempt) {
        room.close();
        return;
      }
      this.room = room;
      this.update({ phase: 'waiting', code: room.code });
      options.onCode?.(room.code);
      const answer = await room.answer;
      if (attempt !== this.attempt) {
        return;
      }
      this.update({ phase: 'connecting' });
      await link.accept(answer);
      await link.opened;
      // Taken: nobody else may join it, and the stub names who played -
      // what the functions bind the room's replays to (ADR 0011). The
      // match goes on without it; its uploads would be refused.
      this.room = null;
      if (attempt === this.attempt) {
        room.take().catch((error: unknown) => {
          console.warn('The room could not be taken', error);
        });
      }
    } catch (error) {
      this.fail(attempt, error);
    }
  }

  /** Joins the room under the code a player typed in. */
  public async join(
    typed: string,
    options: { auto?: boolean } = {}
  ): Promise<void> {
    const rooms = this.cloud.rooms();
    const code = normalizeRoomCode(typed);
    if (rooms === null) {
      return;
    }
    if (code === null) {
      this.update({ notice: { key: 'online.notices.badCode' } });
      return;
    }
    const attempt = this.restart({
      phase: 'connecting',
      role: 'guest',
      code,
      auto: options.auto ?? false,
    });
    try {
      const room = await rooms.join(code);
      if (attempt !== this.attempt) {
        return;
      }
      if (room === null) {
        this.endWith(attempt, { key: 'online.notices.noRoom' });
        return;
      }
      const { link, answer } = await this.wire.answer(room.offer);
      if (!this.adopt(link, attempt)) {
        return;
      }
      await room.answer(answer);
      await link.opened;
    } catch (error) {
      if (errorCode(error) === 'permission-denied') {
        // Another guest answered the room first.
        this.endWith(attempt, { key: 'online.notices.taken' });
        return;
      }
      this.fail(attempt, error);
    }
  }

import type { Observable } from 'rxjs';

/**
 * A direct connection to the other device of an online match: ordered and
 * reliable, for the inputs and the match's messages.
 */
export interface PeerConnection {
  /** What the other device sends, as it sent it. */
  readonly messages$: Observable<string>;
  /** Emits once the connection is gone - closed by either side, or lost. */
  readonly closed$: Observable<void>;
  /**
   * Resolves once the connection is open, rejects when it never opens -
   * with a {@link PeerUnreachableError} when the other device could not be
   * reached at all.
   */
  readonly opened: Promise<void>;
  /** Takes the guest's answer - the host's side of the handshake. */
  accept(answer: string): Promise<void>;
  /** Sends a message, dropped once the connection is no longer open. */
  send(message: string): void;
  close(): void;
}

/**
 * How two devices connect directly: the host makes an offer, the room
 * carries it to the guest, the guest's answer goes back the same way.
 * WebRTC in the game (`WebRtcTransport`), `pairedTransport()` from the
 * lib's testing folder in specs; `OnlineMatchService` injects it through
 * `PEER_TRANSPORT`.
 */
export interface PeerTransport {
  /** True where this device can make a direct connection at all. */
  supported(): boolean;
  /** A connection for the host, with the offer to pass on to the guest. */
  offer(): Promise<{ link: PeerConnection; offer: string }>;
  /** A connection for the guest, answering the host's offer. */
  answer(offer: string): Promise<{ link: PeerConnection; answer: string }>;
}

/**
 * Why the other device could not be reached: `ice_failed` when every way
 * to it failed - strict NATs, which only a relay gets through - and
 * `timeout` when the connection did not open in time.
 */
export type UnreachableKind = 'ice_failed' | 'timeout';

/** The rejection of {@link PeerConnection.opened} for an unreachable device. */
export class PeerUnreachableError extends Error {
  public constructor(public readonly kind: UnreachableKind) {
    super(`The other device could not be reached (${kind}).`);
    this.name = 'PeerUnreachableError';
  }
}
