import {
  replayFromBytes,
  type ReplayHeader,
  replayToBytes,
} from '@wolsok/feat-shared-bacteria-engine';
import {
  boardAvatar,
  storedPlaybackOf,
} from '@wolsok/feat-shared-bacteria-engine/cloud';
import { Timestamp } from 'firebase-admin/firestore';
import { erasePart } from '../erasure/erase';
import { erasureAt } from '../testing/erasure';
import { DAY_MS } from '../boards/budgets';
import type { Verdict } from '../boards/verify';
import { runReplayCommand } from '../replays/command';
import { dailyReplay, TICKS } from '../testing/daily-replay';
import { useEmulatorDb } from '../testing/emulator';
import { featureBest } from './feature-best';
import { publicProfileChanged } from './publish';

/**
 * The gallery against the Firestore emulator (`test-emulator`):
 * `featureBest` picks, re-runs, scores and publishes a day's best match,
 * once, and `remove` takes it down again; the owner's `feature`,
 * `unfeature` and `anonymise` curate it by hand.
 */
const db = useEmulatorDb();

const HOUR = 3_600_000;
/** 04:00 on the 26th: the pick for the 25th. */
import { emulatorEnv } from '@wolsok/shared-firebase-emulator';
import { getApps, initializeApp } from 'firebase-admin/app';
import { type Firestore, getFirestore } from 'firebase-admin/firestore';
import { clearBanCache } from '../limits';

/**
 * The Firestore emulator for an emulator spec (`*.emulator.ts`): starts the
 * admin app on the project `test-emulator` runs (`--project`) once and, before each test, clears
 * the ban cache and every document. Call it once at the spec file's top
 * level, before its own hooks, so they run on the cleared database.
 */
export function useEmulatorDb(): Firestore {
  const project = emulatorEnv('GCLOUD_PROJECT');
  if (getApps().length === 0) {
    initializeApp({ projectId: project });
  }
  beforeEach(async () => {
    clearBanCache();
    await clearFirestore(project);
  });
  return getFirestore();
}

async function clearFirestore(project: string): Promise<void> {
  const response = await fetch(
    `http://${emulatorEnv('FIRESTORE_EMULATOR_HOST')}/emulator/v1/projects/${project}/databases/(default)/documents`,
    { method: 'DELETE' }
  );
  if (!response.ok) {
    throw new Error(`Clearing the emulator failed: ${response.status}`);
  }
}

