cat > plan-turn-key.ts <<'EOF'
/** A TURN key as Cloudflare lists it - its secret is shown only once. */
export interface ListedTurnKey {
  uid: string;
  name: string;
}

/** What `turn-key` does about the TURN key. */
export type TurnKeyPlan =
  /** The key the secret names stays; `remove` are older ones of its name. */
  | { action: 'keep'; uid: string; remove: string[] }
  /**
   * A new key, its secret stored, then `remove` - every older one of the
   * name, whose secret nobody holds any more.
   */
  | { action: 'create'; remove: string[] };

/**
 * Whether the TURN key named `name` is in place: one the secret
 * `CLOUDFLARE_TURN_KEY` names (`storedUid`, null for no secret) is kept,
 * else a new one is made, since Cloudflare shows a key's secret only when
 * it creates it. Keys of other names are never touched.
 */
export function planTurnKey(
  keys: readonly ListedTurnKey[],
  storedUid: string | null,
  name: string
): TurnKeyPlan {
  const ours = keys.filter((key) => key.name === name).map((key) => key.uid);
  if (storedUid !== null && ours.includes(storedUid)) {
    return {
      action: 'keep',
      uid: storedUid,
      remove: ours.filter((uid) => uid !== storedUid),
    };
  }
  return { action: 'create', remove: ours };
}
EOF
cat > plan-usage-alert.ts <<'EOF'
import { isDeepStrictEqual } from 'node:util';

/** A notification policy as Cloudflare's alerting API takes it. */
export interface AlertPolicy {
  name: string;
  alert_type: string;
  enabled: boolean;
  filters: Record<string, string[]>;
  mechanisms: { email: { id: string }[] };
}

/** A policy as Cloudflare lists it, with whatever else it adds. */
export type ListedPolicy = AlertPolicy & { id: string } & Record<string, unknown>;

/** What `turn-key` does about the usage alert. */
export type UsageAlertPlan =
  | { action: 'keep'; id: string; remove: string[] }
  | { action: 'update'; id: string; remove: string[] }
  | { action: 'create'; remove: string[] };

/**
 * Whether the usage alert is in place as `wanted`: found by its name, kept
 * when its type, switch, filters and addresses are the wanted ones,
 * updated otherwise, created when there is none. Other policies of the
 * name are removed.
 */
export function planUsageAlert(
  policies: readonly ListedPolicy[],
  wanted: AlertPolicy
): UsageAlertPlan {
  const [first, ...others] = policies.filter(
    (policy) => policy.name === wanted.name
  );
  const remove = others.map((policy) => policy.id);
  if (first === undefined) {
    return { action: 'create', remove };
  }
  const same =
    first.alert_type === wanted.alert_type &&
    first.enabled === wanted.enabled &&
    isDeepStrictEqual(first.filters, wanted.filters) &&
    isDeepStrictEqual(first.mechanisms, wanted.mechanisms);
  return { action: same ? 'keep' : 'update', id: first.id, remove };
}
EOF
