  const secrets = new FirebaseSecrets();
  if (process.argv.includes('--check')) {
    return (await check(secrets)) ? 0 : 1;
  }
  await provision(secrets);
  return 0;
}

main().then(
  (code) => (process.exitCode = code),
  (error: unknown) => {
    console.error(error instanceof Error ? error.message : error);
    process.exitCode = 1;
  }
);
